//! Microsoft Store packaging: `cargo xtask msix`.
//!
//! Tauri bundles MSI/NSIS only, so this lays out the release exe, the Store icons and
//! a filled-in `packaging/msix/AppxManifest.xml`, then packs it with the Windows SDK's
//! `makeappx`. Several targets are combined into one `.msixbundle`. The packages are
//! unsigned: the Store signs them on upload, and Developer Mode installs them locally.

use super::{APP, app_version, host_triple, run, workspace_root};
use std::fs;
use std::path::{Path, PathBuf};

/// Icons the manifest refers to, generated by `mise run icons` into src-tauri/icons.
const ICONS: &[&str] = &[
    "Square44x44Logo.png",
    "Square150x150Logo.png",
    "StoreLogo.png",
];

struct Identity {
    name: String,
    publisher: String,
    publisher_display_name: String,
    display_name: String,
}

fn identity() -> Result<Identity, String> {
    let path = workspace_root().join("packaging/msix/identity.env");
    let text = fs::read_to_string(&path).map_err(|e| format!("{}: {e}", path.display()))?;
    let get = |key: &str| {
        text.lines()
            .map(str::trim)
            .filter(|l| !l.starts_with('#'))
            .find_map(|l| l.strip_prefix(key)?.strip_prefix('='))
            .map(|v| v.trim().to_string())
            .filter(|v| !v.is_empty())
            .ok_or_else(|| format!("{key} is missing in {}", path.display()))
    };
    Ok(Identity {
        name: get("IDENTITY_NAME")?,
        publisher: get("PUBLISHER")?,
        publisher_display_name: get("PUBLISHER_DISPLAY_NAME")?,
        display_name: get("DISPLAY_NAME")?,
    })
}

fn xml_escape(s: &str) -> String {
    s.replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
        .replace('"', "&quot;")
}

/// MSIX wants four numeric parts, and the Store requires the last one to be 0.
fn msix_version(cargo_version: &str) -> Result<String, String> {
    let parts: Vec<&str> = cargo_version.split('.').collect();
    if parts.len() == 3 && parts.iter().all(|p| p.parse::<u16>().is_ok()) {
        Ok(format!("{cargo_version}.0"))
    } else {
        Err(format!(
            "version `{cargo_version}` can't be an MSIX version; use plain x.y.z (each part ≤ 65535)"
        ))
    }
}

fn msix_arch(target: &str) -> Result<&'static str, String> {
    match target {
        "x86_64-pc-windows-msvc" => Ok("x64"),
        "aarch64-pc-windows-msvc" => Ok("arm64"),
        _ => Err(format!(
            "MSIX packages are Windows-only; unsupported target {target}"
        )),
    }
}

/// Newest copy of a Windows SDK tool (makeappx.exe, ...) for this machine's architecture.
fn sdk_tool(name: &str) -> Result<PathBuf, String> {
    let program_files = std::env::var("ProgramFiles(x86)")
        .map_err(|_| "ProgramFiles(x86) is not set; is this Windows?".to_string())?;
    let bin = Path::new(&program_files).join(r"Windows Kits\10\bin");
    let host = if cfg!(target_arch = "aarch64") {
        "arm64"
    } else {
        "x64"
    };
    let mut found: Vec<(Vec<u32>, PathBuf)> = fs::read_dir(&bin)
        .map_err(|e| format!("{}: {e}; install the Windows SDK", bin.display()))?
        .filter_map(|entry| {
            let entry = entry.ok()?;
            let dir = entry.file_name().into_string().ok()?;
            let version = dir
                .split('.')
                .map(|p| p.parse().ok())
                .collect::<Option<Vec<u32>>>()?;
            let tool = entry.path().join(host).join(name);
            tool.exists().then_some((version, tool))
        })
        .collect();
    found.sort();
    found.pop().map(|(_, tool)| tool).ok_or_else(|| {
        format!(
            "{name} not found under {}; install the Windows SDK",
            bin.display()
        )
    })
}

/// Builds the release exe for `target` and assembles the package folder for it.
fn layout(target: &str, version: &str, id: &Identity) -> Result<PathBuf, String> {
    let arch = msix_arch(target)?;
    run("rustup", &["target", "add", target])?;
    run(
        "cargo",
        &["tauri", "build", "--target", target, "--no-bundle"],
    )?;

    let root = workspace_root();
    let dir = root.join("target").join("msix").join(arch);
    if dir.exists() {
        fs::remove_dir_all(&dir).map_err(|e| format!("clearing {}: {e}", dir.display()))?;
    }
    let assets = dir.join("Assets");
    fs::create_dir_all(&assets).map_err(|e| format!("creating {}: {e}", assets.display()))?;

    let exe = root
        .join("target")
        .join(target)
        .join("release")
        .join(format!("{APP}.exe"));
    copy(&exe, &dir.join(format!("{APP}.exe")))?;
    for icon in ICONS {
        copy(&root.join("src-tauri/icons").join(icon), &assets.join(icon))?;
    }

    let template_path = root.join("packaging/msix/AppxManifest.xml");
    let template = fs::read_to_string(&template_path)
        .map_err(|e| format!("{}: {e}", template_path.display()))?;
    let manifest = template
        .replace("{{IDENTITY_NAME}}", &xml_escape(&id.name))
        .replace("{{PUBLISHER}}", &xml_escape(&id.publisher))
        .replace(
            "{{PUBLISHER_DISPLAY_NAME}}",
            &xml_escape(&id.publisher_display_name),
        )
        .replace("{{DISPLAY_NAME}}", &xml_escape(&id.display_name))
        .replace("{{VERSION}}", version)
        .replace("{{ARCH}}", arch);
    if let Some(start) = manifest.find("{{") {
        let rest = &manifest[start..];
        let end = rest.find("}}").map_or(rest.len(), |i| i + 2);
        return Err(format!(
            "unfilled placeholder in manifest: {}",
            &rest[..end]
        ));
    }
    fs::write(dir.join("AppxManifest.xml"), manifest)
        .map_err(|e| format!("writing manifest: {e}"))?;
    Ok(dir)
}

fn copy(from: &Path, to: &Path) -> Result<(), String> {
    fs::copy(from, to)
        .map(|_| ())
        .map_err(|e| format!("copying {}: {e}", from.display()))
}

fn path_str(p: &Path) -> String {
    p.display().to_string()
}

/// `cargo xtask msix [--target <triple>]...`
pub fn build(args: &[String]) -> Result<(), String> {
    let mut targets = Vec::new();
    let mut rest = args.iter();
    while let Some(arg) = rest.next() {
        match (arg.as_str(), rest.next()) {
            ("--target", Some(t)) => targets.push(t.clone()),
            _ => return Err("usage: cargo xtask msix [--target <triple>]...".to_string()),
        }
    }
    if targets.is_empty() {
        targets.push(host_triple()?);
    }

    let version = msix_version(&app_version()?)?;
    let id = identity()?;
    let makeappx = path_str(&sdk_tool("makeappx.exe")?);

    let root = workspace_root();
    let packages = root.join("target").join("msix").join("packages");
    if packages.exists() {
        fs::remove_dir_all(&packages)
            .map_err(|e| format!("clearing {}: {e}", packages.display()))?;
    }
    fs::create_dir_all(&packages).map_err(|e| format!("creating {}: {e}", packages.display()))?;

    let mut built = Vec::new();
    for target in &targets {
        let dir = layout(target, &version, &id)?;
        let package = packages.join(format!("{APP}_{version}_{}.msix", msix_arch(target)?));
        run(
            &makeappx,
            &[
                "pack",
                "/o",
                "/d",
                &path_str(&dir),
                "/p",
                &path_str(&package),
            ],
        )?;
        built.push(package);
    }

    let dist = root.join("dist");
    fs::create_dir_all(&dist).map_err(|e| format!("creating {}: {e}", dist.display()))?;
    let output = if let [single] = built.as_slice() {
        let out = dist.join(single.file_name().expect("package has a file name"));
        copy(single, &out)?;
        out
    } else {
        let out = dist.join(format!("{APP}_{version}.msixbundle"));
        run(
            &makeappx,
            &[
                "bundle",
                "/o",
                "/bv",
                &version,
                "/d",
                &path_str(&packages),
                "/p",
                &path_str(&out),
            ],
        )?;
        out
    };

    println!("\n{}", output.display());
    if id.name.ends_with(".dev") {
        println!(
            "note: placeholder identity from packaging/msix/identity.env; fine for local \
             testing, but the Store rejects it. Paste your Partner Center values there."
        );
    }
    Ok(())
}

/// Installs the unsigned package for this machine from its folder (Developer Mode).
pub fn register() -> Result<(), String> {
    let version = msix_version(&app_version()?)?;
    let dir = layout(&host_triple()?, &version, &identity()?)?;
    let manifest = dir.join("AppxManifest.xml");
    run(
        "powershell",
        &[
            "-NoProfile",
            "-Command",
            &format!("Add-AppxPackage -Register '{}'", manifest.display()),
        ],
    )?;
    println!("installed; start it from the Start menu or run `tmuxhints` in a new terminal");
    Ok(())
}

pub fn unregister() -> Result<(), String> {
    let id = identity()?;
    run(
        "powershell",
        &[
            "-NoProfile",
            "-Command",
            &format!("Get-AppxPackage -Name '{}' | Remove-AppxPackage", id.name),
        ],
    )
}

/// `cargo xtask msix-wack`: runs the Windows App Certification Kit on the bundle in
/// ./dist and summarizes the report. appcert needs admin rights, so both calls go
/// through Windows `sudo` (you approve a UAC prompt for each).
pub fn wack() -> Result<(), String> {
    let program_files = std::env::var("ProgramFiles(x86)")
        .map_err(|_| "ProgramFiles(x86) is not set; is this Windows?".to_string())?;
    let appcert =
        Path::new(&program_files).join(r"Windows Kits\10\App Certification Kit\appcert.exe");
    if !appcert.exists() {
        return Err(format!(
            "{} not found; install the Windows SDK's App Certification Kit",
            appcert.display()
        ));
    }

    // The kit launches the app; a running copy would receive those launches instead.
    if super::output("tasklist", &["/FI", "IMAGENAME eq tmuxhints.exe", "/NH"])
        .is_some_and(|out| out.contains("tmuxhints.exe"))
    {
        return Err(
            "tmuxhints is running; quit it first (tray menu or `tmuxhints --quit`)".to_string(),
        );
    }

    let root = workspace_root();
    let bundle = fs::read_dir(root.join("dist"))
        .map_err(|e| format!("dist/: {e}; run `mise run msix` first"))?
        .filter_map(|e| e.ok().map(|e| e.path()))
        .find(|p| p.extension().is_some_and(|x| x == "msixbundle"))
        .ok_or("no .msixbundle in dist/; run `mise run msix` first")?;

    let reports = root.join("target").join("wack");
    fs::create_dir_all(&reports).map_err(|e| format!("creating {}: {e}", reports.display()))?;
    let stamp = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map_or(0, |d| d.as_secs());
    // appcert refuses to overwrite an existing report, so every run gets its own file.
    let report = reports.join(format!("report-{stamp}.xml"));

    let appcert = path_str(&appcert);
    println!(
        "Running the App Certification Kit; approve the UAC prompts and leave the machine alone until it finishes."
    );
    run("sudo", &[&appcert, "reset"])?;
    let test = run(
        "sudo",
        &[
            &appcert,
            "test",
            "-appxpackagepath",
            &path_str(&bundle),
            "-reportoutputpath",
            &path_str(&report),
        ],
    );

    let xml = fs::read_to_string(&report).map_err(|e| {
        format!(
            "no report at {} ({e}); appcert result: {test:?}",
            report.display()
        )
    })?;
    let summary = summarize_report(&xml);
    println!("\n{summary}\nfull report: {}", report.display());
    if summary.starts_with("PASS") {
        Ok(())
    } else {
        Err("certification checks did not all pass".to_string())
    }
}

/// Overall result plus every test that didn't pass, from an appcert XML report.
fn summarize_report(xml: &str) -> String {
    let overall = attr(xml, "OVERALL_RESULT").unwrap_or_else(|| "UNKNOWN".to_string());
    let mut lines = vec![overall];
    for test in xml.split("<TEST ").skip(1) {
        let test = test.split("</TEST>").next().unwrap_or(test);
        let result = test
            .split("<RESULT>")
            .nth(1)
            .and_then(|r| r.split("</RESULT>").next())
            .map(|r| {
                r.trim()
                    .trim_start_matches("<![CDATA[")
                    .trim_end_matches("]]>")
                    .trim()
            })
            .unwrap_or("");
        if result.eq_ignore_ascii_case("PASS") || result.is_empty() {
            continue;
        }
        let name = attr(test, "NAME").unwrap_or_else(|| "(unnamed test)".to_string());
        lines.push(format!("  {result}: {name}"));
        for message in test.split("<MESSAGE ").skip(1) {
            if let Some(text) = attr(message, "TEXT") {
                lines.push(format!("      {text}"));
            }
        }
    }
    lines.join("\n")
}

/// Value of the first `name="..."` attribute in `s`.
fn attr(s: &str, name: &str) -> Option<String> {
    let start = s.find(&format!("{name}=\""))? + name.len() + 2;
    let len = s[start..].find('"')?;
    Some(
        s[start..start + len]
            .replace("&quot;", "\"")
            .replace("&amp;", "&"),
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn summarizes_failures_from_a_wack_report() {
        let xml = r#"<?xml version="1.0"?>
<REPORT OVERALL_RESULT="FAIL" VERSION="10.0">
  <REQUIREMENTS>
    <REQUIREMENT NUMBER="1" TITLE="Package sanity">
      <TEST INDEX="1" NAME="Blocked executables" DESCRIPTION="x">
        <RESULT><![CDATA[PASS]]></RESULT>
      </TEST>
      <TEST INDEX="2" NAME="Supported API test" DESCRIPTION="y">
        <RESULT><![CDATA[FAIL]]></RESULT>
        <MESSAGES><MESSAGE TEXT="API Foo in bar.dll is not supported" /></MESSAGES>
      </TEST>
    </REQUIREMENT>
  </REQUIREMENTS>
</REPORT>"#;
        assert_eq!(
            summarize_report(xml),
            "FAIL\n  FAIL: Supported API test\n      API Foo in bar.dll is not supported"
        );
        assert_eq!(
            summarize_report(r#"<REPORT OVERALL_RESULT="PASS">"#),
            "PASS"
        );
    }

    #[test]
    fn versions_get_a_fourth_zero_part() {
        assert_eq!(msix_version("0.1.0").unwrap(), "0.1.0.0");
        assert!(msix_version("0.1").is_err());
        assert!(msix_version("0.1.0-beta").is_err());
        assert!(msix_version("70000.0.0").is_err());
    }

    #[test]
    fn escapes_xml() {
        assert_eq!(
            xml_escape(r#"A & "B" <c>"#),
            "A &amp; &quot;B&quot; &lt;c&gt;"
        );
    }
}
